import re

from moler.exceptions import ParsingDone
from moler.util.converterhelper import ConverterHelper

from ta_moler.cmd.rtg.rtg.genericrtg import GenericRtg

__author__ = "Sylwester Golonka, Dawid Gwizdz"
__copyright__ = "Copyright (C) 2018, Nokia"
__email__ = "sylwester.golonka@nokia.com, dawid.gwizdz@gmail.com"


class Stats(GenericRtg):
    """Stats command class."""

    def __init__(self, connection, options=None, prompt=None, newline_chars=None, runner=None):
        """
        Stats command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameter with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Stats, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self._converter_helper = ConverterHelper()
        self.headers = []
        self.sector = ""
        self.protocol = ""
        self.direct = ""
        self.sigproc = ""
        self.stats_fail_state = ""
        self.device_type = ""
        self.headline = ""
        self.session_id = ""

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "stats"
        cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._start_stats_fail(line)
                self._start_stats_data_dataall_pack(line)
                self._start_stats_sigproc(line)
                self._start_stats_ue(line)
                self._start_stats_executor(line)
            except ParsingDone:
                pass
        return super(Stats, self).on_new_line(line, is_full_line)

    def _start_stats_data_dataall_pack(self, line):
        """
        Start parsing methods if parameter options = 'data' or 'dataall' or 'pack'.

        :param line: Line from device.
        :return: None.
        """
        if self.options in ("data", "dataall", "pack"):
            self._parse_data_headers(line)
            self._parse_data_sector(line)
            self._parse_data_protocol(line)
            self._parse_data_details(line)

    def _start_stats_sigproc(self, line):
        """
        Start parsing methods if parameter options = 'sigproc'.

        :param line: Line from device.
        :return: None.
        """
        if self.options == "sigproc":
            self._parse_sigproc(line)
            self._parse_sigproc_details(line)

    def _start_stats_fail(self, line):
        """
        Start parsing methods if parameter options = 'fail'.

        :param line: Line from device.
        :return: None.
        """
        if self.options == "fail":
            self._parse_stats_fail_states(line)
            self._parse_stats_fail_details(line)

    def _start_stats_ue(self, line):
        """
        Start parsing methods if parameter options = 'ue'.

        :param line: Line from device.
        :return: None.
        """
        if self.options == "ue":
            self._parse_ue_device_type(line)
            self._parse_ue_details(line)

    def _start_stats_executor(self, line):
        """
        Start parsing methods if parameter options = 'executor'.

        :param line: Line from device.
        :return: None.
        """
        if self.options == "executor":
            self._parse_executor_one_row_dict(line)
            self._parse_executor_running_headline(line)
            self._parse_currently_running(line)
            self._parse_executor_running_ue_sessions(line)
            self._parse_executor_running_ue_sessions_details(line)

    _re_stats_fail_states = re.compile(
        r"(?P<STATES>CCCH-NACK|MAX-RLC-RTX|PUCCH-RELEASE-TA-TIMEOUT|RRC-CONNECTION-REJECT|ASYNC-REESTABLISHMENT-FAIL|ASYNC-REESTABLISHMENT|PUCCH-RELEASE-SR-THRESHOLD-EXCEEDED|RA-FAIL)"
    )

    def _parse_stats_fail_states(self, line):
        """
        Remembers the current state if parsing line.

        :param line: Line from device.
        :return:  Nothing but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Stats._re_stats_fail_states, line):
            self.stats_fail_state = self._regex_helper.group("STATES")
            self.current_ret[self.stats_fail_state] = {}
            raise ParsingDone

    _re_stats_fail_details = re.compile(r"\s+(?P<KEY>sector-\d+\$\d+|total)\s+(?P<VALUE>\d+)")

    def _parse_stats_fail_details(self, line):
        """
        Is looking for sector name and number of fails.

        :param line: Line from device.
        :return:  Nothing but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Stats._re_stats_fail_details, line):
            self.current_ret[self.stats_fail_state][self._regex_helper.group("KEY")] = self._regex_helper.group("VALUE")
            raise ParsingDone

    _re_data_headers = re.compile(r"^\s+(?P<COL1>\w+)\s+(?P<COL2>\w+)\s+(?P<COL3>\w+)+\s+(?P<COL4>\w+)")

    def _parse_data_headers(self, line):
        """
        Store the name of the table headers.

        :param line: Line from device.
        :return:  Nothing but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Stats._re_data_headers, line):
            self.headers = []
            self.headers.append(self._regex_helper.group("COL1"))
            self.headers.append(self._regex_helper.group("COL2"))
            self.headers.append(self._regex_helper.group("COL3"))
            self.headers.append(self._regex_helper.group("COL4"))
            raise ParsingDone

    _re_data_sector = re.compile(r"(?P<SECTOR>^(sector-\d+\$\d+|all sectors))")

    def _parse_data_sector(self, line):
        """
        Remembers the current sector if parsing line.

        :param line: Line from device.
        :return:  Nothing but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Stats._re_data_sector, line):
            self.sector = self._regex_helper.group("SECTOR")
            self.current_ret[self.sector] = {}
            raise ParsingDone

    _re_data_protocol = re.compile(r"^\s+(?P<PROTOCOL>udp|tcp|total|ul|dl)")

    def _parse_data_protocol(self, line):
        """
        Parse the data details with tabular output.

        :param line: Line from device.
        :return:  Nothing but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Stats._re_data_protocol, line):
            if self._regex_helper.group("PROTOCOL") in ("udp", "tcp", "total"):
                self.protocol = self._regex_helper.group("PROTOCOL")
                self.direct = "ul&dl"
                self.current_ret[self.sector][self.protocol] = {}
            else:
                self.direct = self._regex_helper.group("PROTOCOL")
            self.current_ret[self.sector][self.protocol][self.direct] = {}

    _re_data_details = re.compile(r"\s+(\d+\.\S+)")

    def _parse_data_details(self, line):
        if self._regex_helper.search(Stats._re_data_details, line):
            ret = re.findall(Stats._re_data_details, line)
            for i in range(len(ret)):
                convert = self._converter_helper.to_bytes(ret[i])
                self.current_ret[self.sector][self.protocol][self.direct][f"{self.headers[i]}_RAW"] = ret[i]
                self.current_ret[self.sector][self.protocol][self.direct][self.headers[i]] = convert[0]
                self.current_ret[self.sector][self.protocol][self.direct][f"{self.headers[i]}_IN_UNIT"] = convert[1]
                self.current_ret[self.sector][self.protocol][self.direct][f"{self.headers[i]}_UNIT"] = convert[2]
            raise ParsingDone

    _re_sigproc = re.compile(r"^(?P<SIGPROC>\w+-?\w+)\s+$")

    def _parse_sigproc(self, line):
        """
        Remembers the current sigproc name if parsing line.

        :param line: Line from device.
        :return:  Nothing but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Stats._re_sigproc, line):
            self.sigproc = self._regex_helper.group("SIGPROC")
            self.current_ret[self.sigproc] = {}
            raise ParsingDone

    _re_sigproc_details = re.compile(r"^\s+(?P<SECTOR>\w+.*?)\s+(?P<ATTEMPTS>\d+)\s+(?P<RATE>\d+\.\d+)\s+(?P<FAIL>\d+)\s+(?P<SUCC>\d+\.\d+\%)")

    def _parse_sigproc_details(self, line):
        """
        Parse the sigproc details with tabular output.

        :param line: Line from device.
        :return:  Nothing but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Stats._re_sigproc_details, line):
            sector = self._regex_helper.group("SECTOR")
            self.current_ret[self.sigproc][sector] = {}
            self.current_ret[self.sigproc][sector]["ATTEMPTS"] = self._regex_helper.group("ATTEMPTS")
            self.current_ret[self.sigproc][sector]["RATE"] = self._regex_helper.group("RATE")
            self.current_ret[self.sigproc][sector]["FAIL"] = self._regex_helper.group("FAIL")
            self.current_ret[self.sigproc][sector]["SUCC"] = self._regex_helper.group("SUCC")
            raise ParsingDone

    _re_device_type = re.compile(r"^(?P<UE>\w+-?\w+)")

    def _parse_ue_device_type(self, line):
        """
        Remembers the device type if parsing line.

        :param line: Line from device.
        :return:  Nothing but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Stats._re_device_type, line):
            self.device_type = self._regex_helper.group("UE")
            self.current_ret[self.device_type] = {}
            raise ParsingDone

    _re_ue_details = re.compile(r"(?P<SECTOR>\w+.*?)\s+(?P<RRC_CONNECTED_UES>\d+)\s+(?P<ACTIVE_BEARERS>\d+)")

    def _parse_ue_details(self, line):
        """
        Parse the ue details with tabular output.

        :param line: Line from device.
        :return:  Nothing but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Stats._re_ue_details, line):
            self.current_ret[self.device_type][self._regex_helper.group("SECTOR")] = {}
            self.current_ret[self.device_type][self._regex_helper.group("SECTOR")]["RRC_CONNECTED_UES"] = self._regex_helper.group(
                "RRC_CONNECTED_UES"
            )
            self.current_ret[self.device_type][self._regex_helper.group("SECTOR")]["ACTIVE_BEARERS"] = self._regex_helper.group("ACTIVE_BEARERS")
            raise ParsingDone

    _re_executor_one_row_dict = re.compile(r"(?P<KEY>^\w+(\s+\w+)*):\s(?P<VALUE>\d+)")

    def _parse_executor_one_row_dict(self, line):
        """
        Parse one row outpt dictionary. example: "scheduled tasks: 168.".

        :param line: Line from device.
        :return:  Nothing but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Stats._re_executor_one_row_dict, line):
            self.current_ret[self._regex_helper.group("KEY")] = self._regex_helper.group("VALUE")
            raise ParsingDone

    _re_executor_running_headline = re.compile(r"(?P<KEY>^\w+(\s+\w+)*):$")

    def _parse_executor_running_headline(self, line):
        """
        Parse headline important for correct parse executor details.

        :param line: Line from device.
        :return:  Nothing but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Stats._re_executor_running_headline, line):
            self.headline = self._regex_helper.group("KEY")
            self.current_ret[self.headline] = {}
            raise ParsingDone

    _re_currently_running = re.compile(r"^\s+(?P<KEY>\S+)\s*:\s+(?P<VALUE>.*)")

    def _parse_currently_running(self, line):
        """
        Parse 'currently runing' table.

        :param line: Line from device.
        :return:  Nothing but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Stats._re_currently_running, line):
            self.current_ret[self.headline][self._regex_helper.group("KEY")] = self._regex_helper.group("VALUE")
            raise ParsingDone

    _re_running_ue_sessions = re.compile(r"(?P<ID>^ID-\d+\s-\s.*):$")

    def _parse_executor_running_ue_sessions(self, line):
        """
        Remember row with id of running ue sessions.

        :param line: Line from device.
        :return:  Nothing but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Stats._re_running_ue_sessions, line):
            self.session_id = self._regex_helper.group("ID")
            self.current_ret[self.headline][self.session_id] = {}
            raise ParsingDone

    _re_running_ue_sessions_details = re.compile(r"-\s(?P<KEY>(\w+\s)*\w+)\s*:\s(?P<VALUE>.*)")

    def _parse_executor_running_ue_sessions_details(self, line):
        """
        Parse details of running ue sessions.

        :param line: Line from device.
        :return:  Nothing but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Stats._re_running_ue_sessions_details, line):
            self.current_ret[self.headline][self.session_id][self._regex_helper.group("KEY")] = self._regex_helper.group("VALUE")
            raise ParsingDone


